inline ::flatbuffers::Offset<DCL> CreateDCL(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> ID = 0,
    int64_t CREATED_AT_MS = 0,
    ::flatbuffers::Offset<::flatbuffers::String> PRODUCER = 0,
    dclProduct PRODUCT = dclProduct_Unspecified,
    ::flatbuffers::Offset<ATM> ATMOSPHERE = 0,
    ::flatbuffers::Offset<PRWJB2008IndicesTable> JB2008_DRIVERS = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<SPW>>> SPACE_WEATHER = 0,
    ::flatbuffers::Offset<::flatbuffers::String> GRAVITY_FIELD = 0,
    uint16_t GRAVITY_DEGREE = 0,
    uint16_t GRAVITY_ORDER = 0,
    double GM_M3_S2 = 0.0,
    double EARTH_ROTATION_RAD_S = 0.0,
    double BALLISTIC_COEFFICIENT_M2_KG = 0.0,
    ::flatbuffers::Offset<dclSettings> SETTINGS = 0,
    ::flatbuffers::Offset<dclCorrection> CORRECTION = 0,
    dclStatus STATUS = dclStatus_Pending,
    ::flatbuffers::Offset<::flatbuffers::String> ERROR_CODE = 0,
    ::flatbuffers::Offset<::flatbuffers::String> ERROR_MESSAGE = 0,
    ::flatbuffers::Offset<dclPoints> POINTS = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<dclObject>>> OBJECTS = 0,
    ::flatbuffers::Offset<dclFitStatistics> FIT = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<dclLevel>>> LEVELS = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<dclIteration>>> HISTORY = 0,
    double LEVEL_LN_B_CORRELATION = std::numeric_limits<double>::quiet_NaN(),
    double MEAN_LEVEL_SIGMA_K = std::numeric_limits<double>::quiet_NaN(),
    ::flatbuffers::Offset<dclStates> STATES = 0) {
  DCLBuilder builder_(_fbb);
  builder_.add_MEAN_LEVEL_SIGMA_K(MEAN_LEVEL_SIGMA_K);
  builder_.add_LEVEL_LN_B_CORRELATION(LEVEL_LN_B_CORRELATION);
  builder_.add_BALLISTIC_COEFFICIENT_M2_KG(BALLISTIC_COEFFICIENT_M2_KG);
  builder_.add_EARTH_ROTATION_RAD_S(EARTH_ROTATION_RAD_S);
  builder_.add_GM_M3_S2(GM_M3_S2);
  builder_.add_CREATED_AT_MS(CREATED_AT_MS);
  builder_.add_STATES(STATES);
  builder_.add_HISTORY(HISTORY);
  builder_.add_LEVELS(LEVELS);
  builder_.add_FIT(FIT);
  builder_.add_OBJECTS(OBJECTS);
  builder_.add_POINTS(POINTS);
  builder_.add_ERROR_MESSAGE(ERROR_MESSAGE);
  builder_.add_ERROR_CODE(ERROR_CODE);
  builder_.add_CORRECTION(CORRECTION);
  builder_.add_SETTINGS(SETTINGS);
  builder_.add_GRAVITY_FIELD(GRAVITY_FIELD);
  builder_.add_SPACE_WEATHER(SPACE_WEATHER);
  builder_.add_JB2008_DRIVERS(JB2008_DRIVERS);
  builder_.add_ATMOSPHERE(ATMOSPHERE);
  builder_.add_PRODUCER(PRODUCER);
  builder_.add_ID(ID);
  builder_.add_GRAVITY_ORDER(GRAVITY_ORDER);
  builder_.add_GRAVITY_DEGREE(GRAVITY_DEGREE);
  builder_.add_STATUS(STATUS);
  builder_.add_PRODUCT(PRODUCT);
  return builder_.Finish();
}

